// Parse a compact duration string such as "1h30m", "45s" or "2d4h" into
// milliseconds.
const UNITS = { d: 86400000, h: 3600000, m: 60000, s: 1000 };

// One optional `<integer><unit>` group per unit, largest unit first, so a
// repeated or out-of-order unit cannot match.
const DURATION_RE = /^(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/;

function parseDuration(input) {
  const groups = typeof input === 'string' ? DURATION_RE.exec(input) : null;
  // The all-optional pattern also matches '', which is not a duration.
  if (groups === null || groups[1] === undefined) {
    throw new RangeError(`invalid duration: ${JSON.stringify(input)}`);
  }

  let total = 0;
  for (let i = 1; i < groups.length; i++) {
    const value = groups[i];
    if (value === undefined) continue;
    const unit = Object.keys(UNITS)[i - 1];
    total += Number(value) * UNITS[unit];
  }
  return total;
}

